String url = "jdbc:postgresql://localhost:5432/tienda";

// 2. Driver: JDBC busca el driver que entiende "jdbc:postgresql:"
// 3. Red: el driver abre una conexión TCP a localhost:5432
// 4. Motor: PostgreSQL valida el usuario y la clave
try (Connection connection = DriverManager.getConnection(url, user, password);
     PreparedStatement ps = connection.prepareStatement("SELECT name FROM products");
     ResultSet rs = ps.executeQuery()) {   // el motor ejecuta el SELECT
    while (rs.next()) {                    // el driver entrega fila por fila
        System.out.println(rs.getString("name"));
    }
}
